        if isinstance(i, int) and 0 <= i < len(coords):
            return coords[i]
        return None

    def dist(a, b):
        ca = coord_of(a)
        cb = coord_of(b)
        if ca is None or cb is None:
            return 0.0
        ax, ay = ca[0], ca[1]
        bx, by = cb[0], cb[1]
        dx = ax - bx
        dy = ay - by
        return (dx * dx + dy * dy) ** 0.5

    if capacity is None:
        capacity = sum(demand_of(i) for i in customers)

    unassigned = set(customers)
    routes = []

    oversized = [i for i in customers if demand_of(i) > capacity]
    for i in oversized:
        routes.append([i])
        if i in unassigned:
            unassigned.remove(i)

    while unassigned:
        seed = None
        best_key = None
        for i in unassigned:
            key = (demand_of(i), dist(depot, i), -i if isinstance(i, int) else 0)
            if best_key is None or key > best_key:
                best_key = key
                seed = i
        route = [seed]
        load = demand_of(seed)
        unassigned.remove(seed)

        while True:
            best = None
            best_key = None
            for i in list(unassigned):
                di = demand_of(i)
                if load + di > capacity:
                    continue
                front_gain = dist(depot, i) + dist(i, route[0]) - dist(depot, route[0])
                back_gain = dist(route[-1], i) + dist(i, depot) - dist(route[-1], depot)
                if front_gain <= back_gain:
                    gain = front_gain
                    pos = 0
                else:
                    gain = back_gain
                    pos = len(route)
                key = (gain, di, -i if isinstance(i, int) else 0)
                if best_key is None or key < best_key:
                    best_key = key
                    best = (i, pos)
            if best is None:
                break
            i, pos = best
            if pos == 0:
                route.insert(0, i)
            else:
                route.append(i)
            load += demand_of(i)
            unassigned.remove(i)

        routes.append(route)

    def route_cost(r):
        if not r:
            return 0.0
        c = dist(depot, r[0]) + dist(r[-1], depot)
        for idx in range(len(r) - 1):
            c += dist(r[idx], r[idx + 1])
        return c

    def load_of(r):
        s = 0
        for x in r:
            s += demand_of(x)
        return s

    improved = True
    guard = 0
    while improved and guard < 4:
        improved = False
        guard += 1

        for ri in range(len(routes)):
            r = routes[ri]
            n = len(r)
            if n < 4:
                continue
            changed = True
            while changed:
                changed = False
                for i in range(n - 2):
                    a = depot if i == 0 else r[i - 1]
                    b = r[i]
                    for k in range(i + 1, n - 1):
                        c = r[k]
                        d = depot if k == n - 1 else r[k + 1]
                        if dist(a, c) + dist(b, d) + 1e-12 < dist(a, b) + dist(c, d):
                            r[i:k + 1] = r[i:k + 1][::-1]
                            changed = True
                            improved = True
                            break
                    if changed:
                        break

        for i in range(len(routes)):
            if improved:
                break
            for j in range(len(routes)):
                if i == j:
                    continue
                ri = routes[i]
                rj = routes[j]
                if not ri:
                    continue
                lj = load_of(rj)
                for idx, x in enumerate(list(ri)):
                    dx = demand_of(x)
                    if lj + dx > capacity:
                        continue
                    best_pos = None
                    best_delta = None
                    for pos in range(len(rj) + 1):
                        left = depot if pos == 0 else rj[pos - 1]
                        right = depot if pos == len(rj) else rj[pos]
                        delta_ins = dist(left, x) + dist(x, right) - dist(left, right)
                        if best_delta is None or delta_ins < best_delta:
                            best_delta = delta_ins
                            best_pos = pos
                    left = depot if idx == 0 else ri[idx - 1]
                    right = depot if idx == len(ri) - 1 else ri[idx + 1]
                    delta_rem = dist(left, right) - dist(left, x) - dist(x, right)
                    if best_delta is not None and delta_rem + best_delta + 1e-12 < 0:
                        ri.pop(idx)
                        rj.insert(best_pos, x)
                        improved = True
                        break
                if improved:
                    break

        routes = [r for r in routes if r]

    seen = {}
    for r in routes:
        for c in r:
            seen[c] = seen.get(c, 0) + 1

    if any(seen.get(i, 0) != 1 for i in customers):
        remaining = list(customers)
        remaining.sort(key=lambda i: (-demand_of(i), -dist(depot, i), i))
        routes = []
        cur = []
        load = 0
        for i in remaining:
            di = demand_of(i)
            if cur and load + di > capacity:
                routes.append(cur)
                cur = [i]
                load = di
            else:
                cur.append(i)
                load += di
        if cur:
            routes.append(cur)

    return routes
